<?php if(!defined('ABSPATH'))exit;$d=woogit_portal_data();get_header();if(!$d['authenticated']){woogit_render_status('error','نشست شما منقضی شده است.');get_footer();return;}$b=$d['billing'];$plans=woogit_plans();$current=woogit_portal_value($b,['plan_id','plan.id'],0);?><section class="wg-section wg-portal"><div class="wg-container"><div class="wg-section__head"><div><span class="wg-eyebrow">اشتراک</span><h1>پلن و دسترسی</h1><p>وضعیت اشتراک از Backend authoritative خوانده می‌شود.</p></div></div><div class="wg-card wg-card--featured"><div class="wg-card__split"><div><span>پلن فعلی</span><h2><?php echo woogit_safe_text(woogit_portal_value($b,['plan_name','plan.name','plan'],'بدون پلن')); ?></h2><p>وضعیت: <?php echo woogit_safe_text(woogit_portal_value($b,['status','subscription_status'],'نامشخص')); ?></p></div><div><span>انقضا / تمدید</span><strong><?php echo woogit_safe_text(woogit_portal_value($b,['next_billing_at','renews_at','expires_at'],'—')); ?></strong></div></div></div><div class="wg-grid wg-grid--3"><?php if(!$plans): ?><article class="wg-card"><strong>پلن‌ها در دسترس نیستند.</strong><p>بعداً دوباره امتحان کنید.</p></article><?php else: foreach($plans as $plan): if(!is_array($plan))continue;$id=(int)($plan['id']??$plan['plan_id']??0);$name=woogit_portal_value($plan,['name','title'],'پلن');$price=woogit_portal_value($plan,['price','amount'],'—');$currency=woogit_portal_value($plan,['currency'],'');$featured=!empty($plan['featured'])||!empty($plan['popular'])||!empty($plan['is_featured']);?><article class="wg-plan<?php echo $featured?' wg-plan--featured':''; ?>"><?php if($featured): ?><span class="wg-plan__badge">پیشنهاد ویژه</span><?php endif; ?><h3><?php echo woogit_safe_text($name); ?></h3><strong><?php echo woogit_safe_text($price); ?> <?php echo woogit_safe_text($currency); ?></strong><?php $features=(array)($plan['features']??[]);if($features): ?><ul><?php foreach($features as $f): ?><li><?php echo woogit_safe_text(is_array($f)?($f['label']??''): $f); ?></li><?php endforeach; ?></ul><?php endif; ?><button class="wg-btn" type="button" data-woogit-checkout data-plan-id="<?php echo esc_attr($id); ?>"><?php echo $id===(int)$current?'تمدید / ادامه':'انتخاب پلن'; ?></button></article><?php endforeach;endif; ?></div></div></section><?php get_footer(); ?>